/* Local user records. Built-in learning data is never changed. */
let customView={kind:'kotoba',level:'all',q:''},customDraft=null,customEditing=null,customDeleteRequest=null;
const CUSTOM_KEYS={kotoba:'gaku-ui-data',kanji:'gaku-ui-kanji'};
function customRead(kind){try{const rows=JSON.parse(localStorage.getItem(CUSTOM_KEYS[kind])||'[]');if(!Array.isArray(rows)||rows.some(r=>!r||typeof r.jp!=='string'||typeof r.meaning!=='string'||(kind==='kanji'&&((r.on!==undefined&&(!Array.isArray(r.on)||r.on.some(x=>typeof x!=='string')))||(r.kun!==undefined&&(!Array.isArray(r.kun)||r.kun.some(x=>typeof x!=='string')))||(r.examples!==undefined&&(!Array.isArray(r.examples)||r.examples.some(x=>!x||['word','kana','meaning'].some(k=>typeof x[k]!=='string'))))))))throw Error();return rows}catch{return null}}
function customId(r,i,kind){return (/^[a-zA-Z0-9_-]{1,100}$/.test(r.customId||'')?r.customId:null)||`${kind==='kotoba'?'custom':'custom-kanji'}-${i}`}
function customRecords(kind){return (customRead(kind)||[]).map((r,i)=>({...r,customId:customId(r,i,kind)}))}
function customNew(){customDraft={level:prefs.level};customEditing=null}
function customChooseKind(kind){if(!Object.hasOwn(CUSTOM_KEYS,kind))return;customView.kind=kind;customNew();render()}
function customField(name,label,placeholder='',required=false){return `<label>${label}<input name="${name}" maxlength="${name==='meaning'?120:name==='mnemonic'?300:80}" value="${esc(customDraft[name]||'')}" placeholder="${esc(placeholder)}" ${required?'required':''} oninput="customDraft['${name}']=this.value"></label>`}
function addData(){if(!customDraft)customNew();const kind=customView.kind,isKanji=kind==='kanji',rows=customRecords(kind),filtered=rows.filter(r=>(customView.level==='all'||(r.level||'N5')===customView.level)&&[r.jp,r.kana,r.rom,r.meaning].join(' ').toLowerCase().includes(customView.q.toLowerCase()));return title('Tambah data','Simpan Kotoba dan Kanji pilihanmu di perangkat ini.')+`<div class="custom-data-page"><div class="custom-tabs" role="group" aria-label="Jenis data">${['kotoba','kanji'].map(k=>`<button type="button" aria-pressed="${kind===k}" onclick="customChooseKind('${k}')">${k==='kotoba'?'ことば · Kotoba':'漢 · Kanji'}</button>`).join('')}</div><section class="panel"><h2>${customEditing?'Edit':'Tambah'} ${isKanji?'Kanji':'Kotoba'}</h2><p class="hint">${isKanji?'Isi satu karakter kanji dan artinya. Bacaan serta contoh boleh ditambahkan jika diketahui.':'Isi kata Jepang, bacaan romaji, dan artinya. Kana boleh ditambahkan.'}</p><form class="form" novalidate onsubmit="submitData(event)"><label>Level materi<select name="level" aria-label="Level data baru" onchange="customDraft.level=this.value">${['N5','N4'].map(l=>`<option value="${l}" ${customDraft.level===l?'selected':''}>${l}</option>`).join('')}</select></label>${customField('jp',isKanji?'Karakter kanji':'Kata bahasa Jepang',isKanji?'Contoh: 森':'Contoh: さくら',true)}${isKanji?customField('on','On’yomi · opsional','Contoh: シン')+customField('kun','Kun’yomi · opsional','Contoh: もり'):customField('kana','Bacaan kana · opsional','Contoh: さくら')+customField('rom','Romaji','Contoh: sakura',true)}${customField('meaning','Arti bahasa Indonesia',isKanji?'Contoh: hutan':'Contoh: bunga sakura',true)}${isKanji?`<details><summary>Tambahkan contoh dan pengingat · opsional</summary><p class="hint">Jika mengisi contoh, lengkapi kata, kana, dan artinya.</p>${customField('exampleWord','Contoh kata','Contoh: 森林')}${customField('exampleKana','Kana contoh','Contoh: しんりん')}${customField('exampleMeaning','Arti contoh','Contoh: hutan')}${customField('mnemonic','Jembatan ingatan','Catatan untuk membantumu mengingat')+customField('radical','Radikal · opsional','Contoh: 木')+customField('strokes','Jumlah guratan · opsional','Contoh: 12')}</details>`:''}<div class="custom-actions"><button class="primary" type="submit">${customEditing?'Simpan perubahan':'Simpan '+(isKanji?'Kanji':'Kotoba')+' ＋'}</button>${customEditing?'<button type="button" onclick="customNew();render()">Batal edit</button>':''}</div><p class="hint">Data masuk ke menu ${isKanji?'Kanji':'Kotoba'} sesuai level. Tersimpan di browser ini.</p></form></section><section class="custom-library"><h2>${isKanji?'Kanji':'Kotoba'} buatanmu <small>(${rows.length})</small></h2><div class="custom-filters"><label>Cari data<input aria-label="Cari data buatanmu" value="${esc(customView.q)}" maxlength="100" placeholder="Kata atau arti…" oninput="customSearch(this.value)"></label><label>Level<select aria-label="Filter level data" onchange="customView.level=this.value;render()">${['all','N5','N4'].map(l=>`<option value="${l}" ${customView.level===l?'selected':''}>${l==='all'?'Semua level':l}</option>`).join('')}</select></label></div><div id="custom-results">${customList(filtered,kind)}</div></section></div>`}
function customList(rows,kind){if(customRead(kind)===null)return '<p role="alert">Data belum dapat dibaca. Penyimpanan tidak diubah; coba muat ulang halaman.</p>';return rows.length?rows.map(r=>`<article class="custom-record"><div><small>${esc(r.level||'N5')} · Buatanmu</small><h3 lang="ja">${esc(r.jp)}</h3><p>${esc(r.kana||r.rom||[r.on,r.kun].flat().filter(Boolean).join(' · '))}</p><b>${esc(r.meaning)}</b></div><div class="custom-actions"><button onclick="customEdit('${esc(r.customId)}')">Edit</button><button class="custom-delete" onclick="customAskDelete('${esc(r.customId)}')">Hapus</button></div></article>`).join(''):'<p class="custom-empty">Belum ada data yang cocok. Tambahkan data atau ubah pencarian.</p>'}
function customSearch(q){customView.q=q.slice(0,100);document.getElementById('custom-results').innerHTML=customList(customRecords(customView.kind).filter(r=>(customView.level==='all'||(r.level||'N5')===customView.level)&&[r.jp,r.kana,r.rom,r.meaning].join(' ').toLowerCase().includes(customView.q.toLowerCase())),customView.kind)}
function customEdit(id){const kind=customView.kind,r=customRecords(kind).find(r=>r.customId===id);if(!r)return;customEditing={id,kind,snapshot:JSON.stringify(r)};customDraft={...r,level:r.level||'N5',on:Array.isArray(r.on)?r.on.join(' / '):r.on||'',kun:Array.isArray(r.kun)?r.kun.join(' / '):r.kun||'',exampleWord:r.examples?.[0]?.word||'',exampleKana:r.examples?.[0]?.kana||'',exampleMeaning:r.examples?.[0]?.meaning||''};render();document.getElementById('app').scrollIntoView?.({block:'start'})}
function customDuplicate(kind,value,id){const key=kotobaWritten(value.jp),base=kind==='kotoba'?kotobaBaseEntries(value.level).flatMap(e=>[e.jp,...e.aliases]):[...KANJI_DATA,...KANJI_N4_DATA].map(k=>k.char);return base.some(w=>kotobaWritten(w)===key)||customRecords(kind).some(r=>r.customId!==id&&(kind==='kanji'||(r.level||'N5')===value.level)&&kotobaWritten(r.jp)===key)}
function customPersist(kind,rows){try{localStorage.setItem(CUSTOM_KEYS[kind],JSON.stringify(rows));if(kind==='kotoba')customData=rows;return true}catch{toast('Belum bisa menyimpan. Periksa penyimpanan browser.');return false}}
function submitData(e){e.preventDefault();const kind=customView.kind,raw=customRead(kind);if(raw===null){toast('Data belum dapat dibaca. Penyimpanan tidak diubah.');return}const rows=customRecords(kind),edit=customEditing,old=edit&&rows.find(r=>r.customId===edit.id);if(edit&&(!old||JSON.stringify(old)!==edit.snapshot)){toast('Data telah berubah. Buka ulang data yang ingin diedit.');return}const f=new FormData(e.target),get=(k,n=80)=>String(f.get(k)||'').trim().slice(0,n),value={...old,jp:get('jp').normalize('NFKC'),meaning:get('meaning',120),level:get('level'),customId:old?.customId||'user-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)};
 if(!value.jp||!value.meaning||!['N5','N4'].includes(value.level)){toast('Lengkapi kata, arti, dan level terlebih dahulu.');return}
 if(kind==='kanji'){if(!/^\p{Script=Han}$/u.test(value.jp)){toast('Isi satu karakter kanji, misalnya 森.');return}value.on=get('on').split(/[,、/\n]+/).map(s=>s.trim()).filter(Boolean);value.kun=get('kun').split(/[,、/\n]+/).map(s=>s.trim()).filter(Boolean);if([...value.on,...value.kun].some(r=>!r.match(/^[\p{Script=Hiragana}\p{Script=Katakana}ー.・\-\s]+$/u))){toast('Isi bacaan kanji memakai kana, misalnya シン atau もり.');return}value.mnemonic=get('mnemonic',300);value.radical=get('radical');const strokes=get('strokes');if((value.radical&&!/^\p{Script=Han}$/u.test(value.radical))||(strokes&&(!/^\d+$/.test(strokes)||Number(strokes)<1||Number(strokes)>64))){toast('Radikal diisi satu karakter; jumlah guratan berupa angka 1–64.');return}value.strokes=strokes?Number(strokes):null;const word=get('exampleWord'),kana=get('exampleKana'),meaning=get('exampleMeaning',120);if((word||kana||meaning)&&(!word||!kana||!meaning||!word.includes(value.jp))){toast('Lengkapi contoh dengan kata yang memuat kanji ini, kana, dan artinya.');return}value.examples=word?[{word,kana,meaning}]:[]}
 else{value.kana=get('kana');value.rom=get('rom');if(!value.rom){toast('Isi romaji agar cara membacanya jelas.');return}}
 if(customDuplicate(kind,value,edit?.id)){toast('Data ini sudah ada. Cari di materi atau daftar buatanmu.');return}const next=edit?rows.map(r=>r.customId===edit.id?value:r):[...rows,value];if(!customPersist(kind,next))return;addHistory('Tambah data',`${edit?'Edit':'Tambah'} ${kind==='kanji'?'Kanji':'Kotoba'}: ${value.jp}`,{level:value.level});customNew();render();toast(edit?'Perubahan tersimpan.':'Data berhasil ditambahkan 🌱')}
function customAskDelete(id){const kind=customView.kind,r=customRecords(kind).find(r=>r.customId===id);if(!r)return;customDeleteRequest={id,kind,snapshot:JSON.stringify(r)};modal(`<h2>Hapus data ini?</h2><p lang="ja">${esc(r.jp)}</p><p>${esc(r.meaning)}</p><p class="hint">Data buatanmu ini akan dihapus dari perangkat ini dan tidak bisa dipulihkan. Materi bawaan tetap tersedia.</p><div class="history-dialog-actions"><button class="primary" onclick="closeModal()">Batal</button><button class="history-confirm-delete" onclick="customConfirmDelete()">Hapus data</button></div>`,'Hapus data buatanmu')}
function customConfirmDelete(){const req=customDeleteRequest;if(!req)return;const raw=customRead(req.kind);if(raw===null){toast('Data belum dapat dibaca. Penyimpanan tidak diubah.');return}const rows=customRecords(req.kind),r=rows.find(r=>r.customId===req.id);if(!r||JSON.stringify(r)!==req.snapshot){closeModal();render();toast('Data telah berubah. Silakan periksa kembali.');return}if(!customPersist(req.kind,rows.filter(r=>r.customId!==req.id)))return;if(customEditing?.id===req.id)customNew();closeModal();render();toast('Data sudah dihapus.')}
function customKanjiEntries(level){const used=new Set([...KANJI_DATA,...KANJI_N4_DATA].map(k=>k.char));return customRecords('kanji').filter(r=>{if((r.level||'N5')!==level||used.has(r.jp))return false;used.add(r.jp);return true}).map((r,i)=>({id:r.customId,char:r.jp,meaning:r.meaning,english:'',level:r.level||'N5',scope:'custom',category:'custom',order:10000+i,on:Array.isArray(r.on)?r.on:[],kun:Array.isArray(r.kun)?r.kun:[],mnemonic:r.mnemonic||'',radical:r.radical||'',strokes:r.strokes||null,examples:r.examples||[],source:{id:'custom'}}))}
const originalKanjiEntries=kanjiEntries,originalKanjiCategories=kanjiCategories,originalFindKanji=findKanji;
kanjiEntries=function(level=prefs.level){return [...originalKanjiEntries(level),...customKanjiEntries(level)]};
kanjiCategories=function(level=prefs.level){return [...originalKanjiCategories(level),...(customKanjiEntries(level).length?[{id:'custom',name:'Buatanmu'}]:[])]};
findKanji=function(query='',category='all',source='all',level=prefs.level,scope='all'){const own=customKanjiEntries(level).filter(k=>(category==='all'||category==='custom')&&(source==='all'||source==='custom')&&(scope==='all'||scope==='custom'||scope==='a2')&&kanjiNormalize([k.char,k.meaning,...k.on,...k.kun,...k.examples.flatMap(e=>[e.word,e.kana,e.meaning])].join(' ')).includes(kanjiNormalize(query)));return [...originalFindKanji(query,category,source,level,scope),...own]};
